/**
 * Length floors, measured over the joined text rather than one section.
 *
 * They are proxies for substance and weak ones: `description` is satisfied by
 * any 80 characters at all, and `requirements` measures the whole
 * conversation. Left as they are because moving them moves the number the
 * Generate BRD control is gated on, which is a product decision.
 */
export const DESCRIPTION_MIN_CHARS = 80
export const REQUIREMENTS_MIN_CHARS = 300
